/* ATtiny3217 (VQFN-24) pin map. Source of truth: projects/led-watch/PINMAP.md (generated by 003 from
 * the board). Keep this file in sync with it.
 *
 *  PA0  UPDI                          PB0  I2C SCL (TWI0)            PC0  LIS2DH12 INT1
 *  PA1  UART TX test pad (USART0 alt) PB1  I2C SDA (TWI0)            PC1  spare
 *  PA2  RTC test pad (EVOUT0)         PB2  TOSC2 (crystal)           PC2  button A
 *  PA3  LED line L0                   PB3  TOSC1 (crystal)           PC3  button B
 *  PA4  LED line L1                   PB4  LED line L8               PC4  spare
 *  PA5  LED line L2                   PB5  LED line L7               PC5  spare
 *  PA6  LED line L3                   PB6  LED line L6
 *  PA7  LED line L4                   PB7  LED line L5
 */
#ifndef BOARD_H
#define BOARD_H
#include <avr/io.h>

#define F_CPU 3333333UL                 /* 20 MHz oscillator / 6 (factory default) */

/* LED lines: L0..L4 = PA3..PA7 (bit = 3 + line), L5..L8 = PB7..PB4 (bit = 12 - line) */
#define LED_PA_MASK  0xF8
#define LED_PB_MASK  0xF0
#define LED_PA_LINES 5                  /* lines 0..4 are on PORTA */

/* Inputs on PORTC, to GND (internal pull-up). Wake from sleep: A and INT1, by LOW LEVEL sensing (PC0 is
 * not a fully asynchronous pin; see main.c, wake_arm). B is only read while awake. */
#define ACC_INT_bm   PIN0_bm            /* LIS2DH12 INT1, active low */
#define BTN_A_bm     PIN2_bm
#define BTN_B_bm     PIN3_bm
#define ACC_I2C_ADDR 0x19               /* SA0 tied high on the board */

#define CALPAD_bm    PIN2_bm            /* on PORTA: RTC/PIT test pad (CAL_OUT build) */
#endif
